/**
 * Циклы ходьбы мага, по 64 поз на цикл:
 *   seedance — по видео Seedance (assets/seedance.mp4): цикл собран ключами в Blender (IK ног, 8 поз,
 *              тайминг и размах — по кадрам видео), экшен mage_walk_keyed в assets/work/mage_rig.blend;
 *   35_01    — запасной: CMU Graphics Lab Motion Capture Database (mocap.cs.cmu.edu; BVH — cgspeed).
 * Фаза как у gait():
 * 0.25 — касание левой стопы, 0.75 — правой. На позу — мировые повороты костей мага относительно
 * покоя (кватернионы x, y, z, w в порядке MAGE.bones) и подъём корпуса (в единицах модели).
 * Сгенерировано (… → walk2ts.mjs), руками не править.
 */

export interface MageWalkClip {
  /** Длительность цикла в записи, сек. */
  cycle: number;
  /** Поз на цикл. */
  n: number;
  q: number[];
  bob: number[];
  /** Путь корпуса за цикл по прямой (x, z на позу, единицы модели): подошва на полу неподвижна. */
  root: number[];
  /** Длина цикла (два шага) вперёд, единицы модели. */
  stride: number;
  /** Связь с видео-источником: фаза клипа в кадре 0, период цикла в кадрах, кадров в секунду. */
  video?: { phase0: number; period: number; fps: number };
}

